import React, { useState, useRef, useEffect } from 'react';

const ImagePositionSelector = ({ imageUrl, initialPosition, onChange }) => {
  const containerRef = useRef(null);
  const imageRef = useRef(null);
  const [isDragging, setIsDragging] = useState(false);
  const [position, setPosition] = useState({ x: 50, y: 50 }); // Default center position (50%, 50%)
  const [imageSize, setImageSize] = useState({ width: 0, height: 0 });
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  // Parse initial position into x, y percentages
  useEffect(() => {
    if (initialPosition) {
      const positionMap = {
        'center': { x: 50, y: 50 },
        'top': { x: 50, y: 0 },
        'bottom': { x: 50, y: 100 },
        'left': { x: 0, y: 50 },
        'right': { x: 100, y: 50 },
        'top left': { x: 0, y: 0 },
        'top right': { x: 100, y: 0 },
        'bottom left': { x: 0, y: 100 },
        'bottom right': { x: 100, y: 100 }
      };
      
      setPosition(positionMap[initialPosition] || { x: 50, y: 50 });
    }
  }, [initialPosition]);

  // Update container and image sizes on mount and resize
  useEffect(() => {
    const updateSizes = () => {
      if (containerRef.current && imageRef.current) {
        setContainerSize({
          width: containerRef.current.offsetWidth,
          height: containerRef.current.offsetHeight
        });
        
        // We need to get the natural dimensions of the image
        const img = new Image();
        img.src = imageUrl;
        img.onload = () => {
          setImageSize({
            width: img.naturalWidth,
            height: img.naturalHeight
          });
        };
      }
    };

    updateSizes();
    window.addEventListener('resize', updateSizes);
    
    return () => {
      window.removeEventListener('resize', updateSizes);
    };
  }, [imageUrl]);

  // Convert position to CSS background-position
  useEffect(() => {
    const backgroundPosition = `${position.x}% ${position.y}%`;
    onChange(backgroundPosition);
  }, [position, onChange]);

  const handleMouseDown = (e) => {
    setIsDragging(true);
    updatePosition(e);
  };

  const handleMouseMove = (e) => {
    if (isDragging) {
      updatePosition(e);
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleTouchStart = (e) => {
    setIsDragging(true);
    updatePositionTouch(e);
  };

  const handleTouchMove = (e) => {
    if (isDragging) {
      updatePositionTouch(e);
    }
  };

  const handleTouchEnd = () => {
    setIsDragging(false);
  };

  const updatePosition = (e) => {
    if (!containerRef.current) return;
    
    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(100, ((e.clientX - rect.left) / rect.width) * 100));
    const y = Math.max(0, Math.min(100, ((e.clientY - rect.top) / rect.height) * 100));
    
    setPosition({ x, y });
  };

  const updatePositionTouch = (e) => {
    if (!containerRef.current || !e.touches[0]) return;
    
    const rect = containerRef.current.getBoundingClientRect();
    const touch = e.touches[0];
    const x = Math.max(0, Math.min(100, ((touch.clientX - rect.left) / rect.width) * 100));
    const y = Math.max(0, Math.min(100, ((touch.clientY - rect.top) / rect.height) * 100));
    
    setPosition({ x, y });
  };

  return (
    <div className="image-position-selector">
      <div className="position-preview-container">
        <div 
          ref={containerRef}
          className="position-preview"
          style={{
            backgroundImage: `url(${imageUrl})`,
            backgroundPosition: `${position.x}% ${position.y}%`,
            backgroundSize: 'cover',
            cursor: isDragging ? 'grabbing' : 'grab'
          }}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
        >
          <div 
            ref={imageRef}
            className="position-indicator"
            style={{
              left: `${position.x}%`,
              top: `${position.y}%`
            }}
          ></div>
          <div className="position-instructions">
            Drag to adjust image position
          </div>
        </div>
      </div>
      <div className="position-controls">
        <button 
          type="button" 
          className="position-preset"
          onClick={() => setPosition({ x: 50, y: 50 })}
        >
          Center
        </button>
        <div className="position-values">
          X: {Math.round(position.x)}%, Y: {Math.round(position.y)}%
        </div>
      </div>
    </div>
  );
};

export default ImagePositionSelector;
